def power(base, exp):
    """Calculates base^exp, handling integer constraints."""
    if exp == 0:
        return 1
    if base == 0:
        return 0 if exp > 0 else None # Undefined or zero

    try:
        return base ** exp
    except OverflowError:
        return None # Result too large
    except Exception:
        # Handles cases where exp is negative and base is not +/- 1
        return None 

def calculate_N(x, y, z):
    """Calculates N = y^x * z^y * x^z, returning None if not an integer."""

    # Check for base constraints based on exponent rules for integer results
    # N must be an integer (a prime).

    # Term 1: y^x
    t1 = power(y, x)
    if t1 is None:
        return None

    # Term 2: z^y
    t2 = power(z, y)
    if t2 is None:
        return None

    # Term 3: x^z
    t3 = power(x, z)
    if t3 is None:
        return None

    N = t1 * t2 * t3
    return N

def solve_task():
    MAX_S = 100

    # Since x^2, y^2, z^2 <= 100, we search x, y, z in [-10, 10]
