def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def evaluate_n(x, y, z):
    # N = y^x * z^y * x^z

    # Handle zero bases and exponents carefully

    # Term 1: y^x
    if y == 0:
        if x > 0:
            T1 = 0
        elif x == 0:
            T1 = 1 # Convention 0^0 = 1
        else: # x < 0
            # 0 raised to a negative power is undefined (division by zero)
            return None 
    elif y == 1:
        T1 = 1
    elif y == -1:
        T1 = 1 if x % 2 == 0 else -1
    else:
        try:
            T1 = y**x
        except OverflowError:
            return None # Too large

    # Term 2: z^y
    if z == 0:
        if y > 0:
            T2 = 0
        elif y == 0:
            T2 = 1
        else: # y < 0
            return None
    elif z == 1:
        T2 = 1
    elif z == -1:
        T2 = 1 if y % 2 == 0 else -1
    else:
        try:
            T2 = z**y
        except OverflowError:
            return None

    # Term 3: x^z
    if x == 0:
        if z > 0:
            T3 = 0
        elif z == 0:
            T3 = 1
        else: # z < 0
            return None
    elif x == 1:
        T3 = 1
    elif x == -1:
        T3 = 1 if z % 2 == 0 else -1
    else:
        try:
            T3 = x**z
        except OverflowError:
            return None

    N = T1 * T2 * T3
    return N

